    salao_modo: 'ambos',
    recibo_impressora_id: '',
    auto_atendimento_habilitado: false,
  });
  const [impressoras, setImpressoras] = useState([]);

  useEffect(() => {
    if (tipoRestaurante) listarImpressoras().then(setImpressoras).catch(() => {});
  }, [tipoRestaurante]);

  useEffect(() => {
    getConfig()
      .then((d) => {
        setConfig(d);
        setForm((f) => ({
          ...f,
